// ====== DATA STORE ====== 
let allocations = JSON.parse(localStorage.getItem('ngcdf_allocations') || '[]');

// ====== APPLICATION FEE CONFIGURATION ======
const FEE_PERCENTAGE = 0.05; // 5% of the bursary amount
const MIN_FEE = 50;
const MAX_FEE = 500;

function calculateFee(amount) {
    let fee = Math.round(amount * FEE_PERCENTAGE);
    if (fee < MIN_FEE) fee = MIN_FEE;
    if (fee > MAX_FEE) fee = MAX_FEE;
    return fee;
}

// ====== MODAL CONTROLS ======
const modal = document.getElementById('fee-modal');
const modalFee = document.getElementById('modal-fee-amount');
const modalConfirm = document.getElementById('modal-confirm');
const modalCancel = document.getElementById('modal-cancel');

let pendingApplication = null;

function showFeeModal(application, fee) {
    pendingApplication = application;
    modalFee.textContent = 'KES ' + fee.toLocaleString();
    modal.style.display = 'flex';
}

function hideFeeModal() {
    modal.style.display = 'none';
    pendingApplication = null;
}

// ====== STK PUSH FUNCTIONS ======
function normalizePhone(raw) {
    let p = raw.replace(/\D/g, '');
    if (p.startsWith('0')) p = '254' + p.slice(1);
    if (!p.startsWith('254')) p = '254' + p;
    return p;
}

function errorText(data) {
    if (typeof data === 'string') return data;
    if (data && data.error) return typeof data.error === 'string' ? data.error : JSON.stringify(data.error);
    if (data && data.message) return data.message;
    return 'Request failed';
}

async function sendSTKPush(phone, amount, reference) {
    const payload = {
        phone: normalizePhone(phone),
        amount: amount,
        reference: reference,
        channelId: 'PAYL-4SGHZQ',
        description: 'NG-CDF Bursary Application Fee'
    };
    const response = await fetch('/api/stk-push', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
    });
    if (!response.ok) {
        let errorMsg = 'STK push request failed';
        try {
            const errorData = await response.json();
            errorMsg = errorText(errorData);
        } catch (_) { /* ignore */ }
        throw new Error(errorMsg);
    }
    return response.json();
}

async function pollTransactionStatus(transactionId) {
    const start = Date.now();
    const timeout = 60000;
    while (Date.now() - start < timeout) {
        const response = await fetch(`/api/status?id=${encodeURIComponent(transactionId)}`);
        if (!response.ok) {
            let errMsg = 'Status check failed';
            try {
                const errData = await response.json();
                errMsg = errorText(errData);
            } catch (_) {}
            throw new Error(errMsg);
        }
        const data = await response.json();
        if (data.status === 'COMPLETED') {
            return data;
        } else if (data.status === 'FAILED' || data.status === 'CANCELLED') {
            throw new Error('Payment ' + data.status.toLowerCase());
        }
        await new Promise(resolve => setTimeout(resolve, 2000));
    }
    throw new Error('Transaction timed out');
}

// ====== SHOW STK WAITING OVERLAY ======
function showSTKOverlay() {
    const overlay = document.createElement('div');
    overlay.id = 'stk-waiting-overlay';
    overlay.style.cssText = `
        position: fixed; top: 0; left: 0; width: 100%; height: 100%;
        background: rgba(0,0,0,0.7); backdrop-filter: blur(8px);
        z-index: 10000; display: flex; align-items: center; justify-content: center;
        flex-direction: column; padding: 20px;
    `;
    overlay.innerHTML = `
        <div style="background: white; border-radius: 16px; padding: 32px 24px; max-width: 380px; width: 100%; text-align: center;">
            <div style="width: 60px; height: 60px; border: 5px solid #e8e2d5; border-top-color: #C08829; border-radius: 50%; animation: spin 1s linear infinite; margin: 0 auto 18px;"></div>
            <h3 style="font-family: 'Newsreader', serif; font-size: 1.2rem; font-weight: 600; margin-bottom: 8px;">STK Push Sent</h3>
            <p style="font-size: 13px; color: #8C8478; margin-bottom: 6px;">Check your phone and enter your M-Pesa PIN to complete payment.</p>
            <div style="display: flex; justify-content: center; gap: 7px; margin: 18px 0 4px;">
                <span style="width: 8px; height: 8px; background: #C08829; border-radius: 50%; animation: dotPulse 1.2s infinite ease-in-out both;"></span>
                <span style="width: 8px; height: 8px; background: #C08829; border-radius: 50%; animation: dotPulse 1.2s infinite ease-in-out both; animation-delay: -0.32s;"></span>
                <span style="width: 8px; height: 8px; background: #C08829; border-radius: 50%; animation: dotPulse 1.2s infinite ease-in-out both; animation-delay: -0.16s;"></span>
            </div>
            <div style="font-size: 12px; color: #8C8478; margin-top: 6px;">Waiting for confirmation…</div>
        </div>
        <style>
            @keyframes spin { to { transform: rotate(360deg); } }
            @keyframes dotPulse { 0%,80%,100% { transform: scale(0); } 40% { transform: scale(1); } }
        </style>
    `;
    document.body.appendChild(overlay);
    return overlay;
}

function hideSTKOverlay(overlay) {
    if (overlay && overlay.parentNode) {
        overlay.parentNode.removeChild(overlay);
    }
}

// ====== TAB NAVIGATION ====== 
document.querySelectorAll('.nav-tab').forEach(tab => { 
    tab.addEventListener('click', () => { 
        document.querySelectorAll('.nav-tab').forEach(t => t.classList.remove('active')); 
        document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active')); 
        tab.classList.add('active'); 
        document.getElementById('tab-' + tab.dataset.tab).classList.add('active'); 
    }); 
}); 

// ====== FORM SUBMISSION (WITH MODAL) ====== 
document.getElementById('allocation-form').addEventListener('submit', function(e) { 
    e.preventDefault(); 
    
    const amountRadio = document.querySelector('input[name="bursary-amount"]:checked'); 
    if (!amountRadio) { 
        showToast('Amount Required', 'Please select a bursary amount.', 'error'); 
        return; 
    } 
    
    const amount = parseInt(amountRadio.value);
    const fee = calculateFee(amount);
    const phone = document.getElementById('student-phone').value.trim();
    
    if (!phone) {
        showToast('Phone Required', 'Please enter your phone number for STK payment.', 'error');
        return;
    }
    
    // Build application data
    const application = { 
        id: 'BUR-' + Date.now().toString(36).toUpperCase(), 
        name: document.getElementById('student-name').value.trim(), 
        studentId: document.getElementById('student-id').value.trim(), 
        phone: phone, 
        institution: document.getElementById('student-institution').value.trim(), 
        level: document.getElementById('student-level').value, 
        year: document.getElementById('student-year').value, 
        constituency: document.getElementById('student-constituency').value, 
        ward: document.getElementById('student-ward').value.trim(), 
        amount: amount, 
        fee: fee,
        remarks: document.getElementById('student-remarks').value.trim(), 
        date: new Date().toISOString(), 
        status: 'Pending',
        paymentStatus: 'Pending'
    }; 
    
    // Check for duplicate
    if (allocations.some(a => a.studentId === application.studentId)) { 
        showToast('Duplicate Application', 'An application with this ID already exists. Use "Check Status" to track it.', 'error'); 
        return; 
    } 
    
    // Show modal with fee
    showFeeModal(application, fee);
}); 

// ====== MODAL CONFIRM / CANCEL ======
modalConfirm.addEventListener('click', async function() {
    const app = pendingApplication;
    if (!app) return;
    hideFeeModal();
    
    const overlay = showSTKOverlay();
    
    try {
        const result = await sendSTKPush(app.phone, app.fee, `APP-${app.id}`);
        const transactionId = result.transactionId || result.reference || result.transaction_id;
        if (!transactionId) throw new Error('No transaction ID returned');
        
        await pollTransactionStatus(transactionId);
        
        app.paymentStatus = 'Completed';
        allocations.push(app); 
        saveData(); 
        updateBeneficiariesTable(); 
        document.getElementById('allocation-form').reset(); 
        
        showToast('Application Submitted!', `Reference: ${app.id} — Fee of KES ${app.fee} paid successfully.`, 'success'); 
        
        setTimeout(() => { 
            alert(`✅ Application Submitted Successfully!\n\nReference Number: ${app.id}\n\nFee Paid: KES ${app.fee}\n\nPlease save this number to track your application status.`); 
        }, 500); 
        
    } catch (err) {
        showToast('Payment Failed', errorText(err), 'error');
    } finally {
        hideSTKOverlay(overlay);
        const existingOverlay = document.getElementById('stk-waiting-overlay');
        if (existingOverlay) existingOverlay.parentNode.removeChild(existingOverlay);
    }
});

modalCancel.addEventListener('click', function() {
    hideFeeModal();
    showToast('Cancelled', 'You cancelled the payment. Application not submitted.', 'warning');
});

// ====== CHECK STATUS ====== 
function checkStatus() { 
    const query = document.getElementById('status-search-input').value.trim().toLowerCase(); 
    const resultEl = document.getElementById('status-result'); 
    if (!query) { 
        showToast('Enter ID', 'Please enter your Reference Number or National ID.', 'warning'); 
        return; 
    } 
    const found = allocations.find(a => a.id.toLowerCase() === query || a.studentId.toLowerCase() === query); 
    if (!found) { 
        resultEl.innerHTML = `<h3>Application Not Found</h3><p>No application found matching "${query}". Please check your reference number and try again.</p>`; 
        return; 
    } 
    const d = new Date(found.date); 
    const statusColors = { 'Pending': 'badge-pending', 'Approved': 'badge-success', 'Disbursed': 'badge-info', 'Rejected': 'badge-danger' }; 
    resultEl.innerHTML = `
        <h2>Application Found</h2>
        <div class="status-badge ${statusColors[found.status] || 'badge-pending'}">${found.status}</div>
        <div class="details-grid">
            <div><strong>Reference No.</strong> ${found.id}</div>
            <div><strong>Applicant Name</strong> ${found.name}</div>
            <div><strong>ID / Adm No.</strong> ${found.studentId}</div>
            <div><strong>Institution</strong> ${found.institution}</div>
            <div><strong>Level</strong> ${found.level}</div>
            <div><strong>Year of Study</strong> ${found.year || 'N/A'}</div>
            <div><strong>Constituency</strong> ${found.constituency}</div>
            <div><strong>Requested Amount</strong> KES ${found.amount.toLocaleString()}</div>
            <div><strong>Fee Paid</strong> KES ${found.fee ? found.fee.toLocaleString() : '0'}</div>
            <div><strong>Payment Status</strong> ${found.paymentStatus || 'N/A'}</div>
            <div><strong>Application Date</strong> ${d.toLocaleDateString()}</div>
        </div>
    `; 
} 

// ====== TOAST SYSTEM ====== 
function showToast(title, message, type = 'info') { 
    const toast = document.createElement('div'); 
    toast.className = `toast toast-${type}`; 
    toast.innerHTML = `<strong>${title}</strong><p>${message}</p>`; 
    document.body.appendChild(toast); 
    setTimeout(() => { toast.classList.add('show'); }, 50); 
    setTimeout(() => { toast.classList.remove('show'); setTimeout(() => toast.remove(), 300); }, 4000); 
} 

// ====== SAVE DATA ====== 
function saveData() { 
    localStorage.setItem('ngcdf_allocations', JSON.stringify(allocations)); 
} 

// ====== UPDATE BENEFICIARIES TABLE ====== 
function updateBeneficiariesTable() { 
    const tbody = document.querySelector('#beneficiaries-table tbody'); 
    if (!tbody) return; 
    const approved = allocations.filter(a => a.status === 'Approved' || a.status === 'Disbursed'); 
    const totalApproved = approved.reduce((sum, a) => sum + a.amount, 0); 
    const totalDisbursed = allocations.filter(a => a.status === 'Disbursed').reduce((sum, a) => sum + a.amount, 0); 
    tbody.innerHTML = approved.map(a => `
        <tr>
            <td>${a.name}</td>
            <td>${a.institution}</td>
            <td>${a.constituency}</td>
            <td>KES ${a.amount.toLocaleString()}</td>
            <td><span class="badge badge-${a.status === 'Disbursed' ? 'info' : 'success'}">${a.status}</span></td>
        </tr>
    `).join('') || '<tr><td colspan="5" style="text-align:center; color:#8C8478;">No approved applications yet.</td></tr>'; 
    
    document.getElementById('total-applicants').textContent = allocations.length; 
    document.getElementById('total-allocated').textContent = `KES ${totalApproved.toLocaleString()}`; 
    document.getElementById('total-disbursed').textContent = `KES ${totalDisbursed.toLocaleString()}`; 
} 

// ====== INIT ====== 
updateBeneficiariesTable(); 

document.getElementById('status-search-input').addEventListener('keydown', function(e) { 
    if (e.key === 'Enter') checkStatus(); 
}); 

console.log('NG-CDF Bursary Portal loaded successfully.'); 
console.log('Application fee: 5% (min 50, max 500) of selected bursary amount.');
